-- ============================================
-- LUMA — Thème 14 : LONG 1/3 x4 — Un road trip complet sur plusieurs villes avec péripéties
-- ============================================


update scenarios set content = '{"characters": {"friend": "ton ami(e)", "app_alert": "alerte météo", "local": "un local"}, "start_node": "n1", "nodes": {"n1": {"speaker": "friend", "text": "First stop, Nashville! I''ve heard the music scene here is incredible.", "text_fr": "Premier arrêt, Nashville ! J''ai entendu dire que la scène musicale ici est incroyable.", "choices": [{"text": "Let''s find a live music venue tonight, I can''t wait!", "text_fr": "Trouvons une salle de musique live ce soir, j''ai hâte !", "next": "n2"}, {"text": "Maybe we should check into our hotel first, then explore.", "text_fr": "On devrait peut-être d''abord aller à l''hôtel, puis explorer.", "next": "n2b"}]}, "n2": {"speaker": "you_thought", "text": "(You find an incredible local bar with a live country band playing.)", "text_fr": "(Vous trouvez un incroyable bar local avec un groupe de country jouant en live.)", "choices": [{"text": "(Enjoy the music and grab a table near the stage.)", "text_fr": "(Profite de la musique et prends une table près de la scène.)", "next": "n3"}]}, "n2b": {"speaker": "friend", "text": "Good call, let''s settle in first so we can really enjoy the night after.", "text_fr": "Bonne idée, installons-nous d''abord pour vraiment profiter de la soirée après.", "choices": [{"text": "(After checking in, head out to find live music.)", "text_fr": "(Après avoir enregistré, sors trouver de la musique live.)", "next": "n3"}]}, "n3": {"speaker": "friend", "text": "This is exactly the kind of night I hoped we''d have on this trip!", "text_fr": "C''est exactement le genre de soirée que j''espérais qu''on aurait pendant ce voyage !", "choices": [{"text": "Me too, this is such a great start to our road trip.", "text_fr": "Moi aussi, c''est un si bon début pour notre road trip.", "next": "n4"}]}, "n4": {"speaker": "you_thought", "text": "(Two days later, driving toward New Orleans, dark clouds gather ominously ahead.)", "text_fr": "(Deux jours plus tard, en conduisant vers La Nouvelle-Orléans, de sombres nuages s''amassent de façon menaçante devant.)", "choices": [{"text": "(Check weather updates on your phone.)", "text_fr": "(Vérifie les mises à jour météo sur ton téléphone.)", "next": "n5"}]}, "n5": {"speaker": "app_alert", "text": "Severe thunderstorm warning issued for your route. Consider delaying travel.", "text_fr": "Alerte d''orage sévère émise pour votre itinéraire. Envisagez de retarder le voyage.", "choices": [{"text": "Let''s find a safe place to wait out the storm.", "text_fr": "Trouvons un endroit sûr pour attendre que l''orage passe.", "next": "n6"}, {"text": "We could try an alternate route to avoid the worst of it.", "text_fr": "On pourrait essayer un itinéraire alternatif pour éviter le pire.", "next": "n6b"}]}, "n6": {"speaker": "friend", "text": "There''s a rest stop up ahead, let''s pull over there until it passes.", "text_fr": "Il y a une aire de repos plus loin, arrêtons-nous là jusqu''à ce que ça passe.", "choices": [{"text": "Good thinking, better safe than risking driving through that.", "text_fr": "Bonne pensée, mieux vaut être prudent plutôt que risquer de conduire à travers ça.", "next": "n7"}]}, "n6b": {"speaker": "friend", "text": "Let''s check the map for alternate routes, though it might add some time.", "text_fr": "Vérifions la carte pour des itinéraires alternatifs, même si ça pourrait rajouter du temps.", "choices": [{"text": "Worth it if it keeps us safer overall.", "text_fr": "Ça vaut le coup si ça nous garde plus en sécurité dans l''ensemble.", "next": "n7"}]}, "n7": {"speaker": "you_thought", "text": "(After a tense hour of waiting, the storm passes, leaving the road clear but wet.)", "text_fr": "(Après une heure tendue d''attente, l''orage passe, laissant la route dégagée mais mouillée.)", "choices": [{"text": "(Get back on the road carefully, relieved the worst has passed.)", "text_fr": "(Reprends la route prudemment, soulagé que le pire soit passé.)", "next": "n8"}]}, "n8": {"speaker": "friend", "text": "We made it! New Orleans looks even more magical than I imagined.", "text_fr": "On y est arrivés ! La Nouvelle-Orléans a l''air encore plus magique que ce que j''imaginais.", "choices": [{"text": "Let''s explore the French Quarter first, I''ve heard it''s unmissable.", "text_fr": "Explorons le Quartier Français d''abord, j''ai entendu dire que c''est incontournable.", "next": "n9"}]}, "n9": {"speaker": "local", "text": "First time in New Orleans? You have to try the beignets at Café du Monde!", "text_fr": "Première fois à La Nouvelle-Orléans ? Vous devez essayer les beignets au Café du Monde !", "choices": [{"text": "We''ll definitely check that out, thank you for the tip!", "text_fr": "On va définitivement aller voir ça, merci pour le conseil !", "next": "n10"}]}, "n10": {"speaker": "you_thought", "text": "(After beignets and jazz music, the trip feels complete, more than you''d hoped.)", "text_fr": "(Après les beignets et la musique jazz, le voyage semble complet, plus que vous ne l''espériez.)", "choices": [{"text": "(Reflect on the whole journey — Nashville''s music, the storm, and now this.)", "text_fr": "(Réfléchis à tout le voyage — la musique de Nashville, l''orage, et maintenant ça.)", "next": "n11"}]}, "n11": {"speaker": "friend", "text": "Despite the storm scare, this has honestly been the best trip of my life.", "text_fr": "Malgré la frayeur de l''orage, ça a honnêtement été le meilleur voyage de ma vie.", "choices": [{"text": "Same here. Adventures wouldn''t be memorable without a little chaos, right?", "text_fr": "Pareil pour moi. Les aventures seraient pas mémorables sans un peu de chaos, non ?", "next": "end_journey"}]}, "end_journey": {"speaker": "friend", "text": "Exactly! Nashville, the storm, New Orleans — every bit of it made this unforgettable.", "text_fr": "Exactement ! Nashville, l''orage, La Nouvelle-Orléans — chaque partie a rendu ça inoubliable.", "end": true, "ending_label": "Road trip multi-villes inoubliable malgré les péripéties 🚗🎷🌩️"}}}'::jsonb, is_playable = true
where title = 'Un road trip complet sur plusieurs villes avec péripéties'
  and theme_id = (select id from scenario_themes where position = 14 and language_id = (select id from languages where code = 'en'));
